def get_adjacent_tuples(grid, row, col):
    """Return the 4 orthogonal adjacent tuples (up, down, left, right) of a cell."""
    adjacent = []
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    for dr, dc in directions:
        r, c = row + dr, col + dc
        if 0 <= r < len(grid) and 0 <= c < len(grid[0]):
            adjacent.append(tuple(grid[r][c]))
    return adjacent


def get_coordinates(grid, *points):
    """Return coordinates of the given points in the grid."""
    coords = []
    for point in points:
        for r, row in enumerate(grid):
            for c, value in enumerate(row):
                if tuple(value) == tuple(point):
                    coords.append((r, c))
    return coords


grid = [
